WITH deduped AS (SELECT id, method, amount FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY amount DESC, id) AS dedup_rank FROM payments) x WHERE dedup_rank = 1) SELECT CASE WHEN amount >= 1740 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, STDDEV_SAMP(amount) AS amount_stddev, COUNT(*) AS row_count, COUNT(*) FILTER (WHERE method = 'card') AS card_rows FROM deduped GROUP BY CUBE (CASE WHEN amount >= 1740 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY amount_tier DESC
